// _signed_cloneMapStringInt returns a copy of x, a map[string]int, and nil for
// a nil x.
func _signed_cloneMapStringInt(x map[string]int) map[string]int {
	if x == nil {
		return nil
	}
	c := make(map[string]int, len(x))
	for mk, mv := range x {
		c[strings.Clone(mk)] = mv
	}
	return c
}

